// Üretilen dosya: tool/ozgun/uret.py. Müzik · Orta Çağ, Rönesans ve Barok müziği: formlar, çalgılar ve besteciler (madrigal, füg, konçerto grosso, oratoryo, klavsen, Vivaldi, Bach, Handel, Monteverdi) (kolay).
const ozMusic15Kolay = <(String, String, List<String>, String)>[
  ('Batı kilise müziğinin temelini oluşturan Gregoryen ezgilerinin doku bakımından en belirgin niteliği aşağıdakilerden hangisidir?', 'Eşliksiz tek sesli vokal çizgiden oluşması', ['Dört sesli koral armoni kurallarına dayanması', 'Sürekli bas eşliğinde doğaçlama icra edilmesi', 'Yaylı çalgılar grubuyla çift koro halinde söylenmesi'], 'Gregoryen düz ezgileri (plainchant), herhangi bir çalgı eşliği veya armonik çokseslilik içermeyen saf monofonik (tek sesli) dini vokal ezgilerdir.'),
  ('11. yüzyılda dört çizgili dizek sistemini geliştirerek solfej hecelerinin temelini atan müzik kuramcısı kimdir?', 'Arezzolu Guido', ['Bingenli Hildegard', 'Kölnlü Franco', 'boethiuslu Severinus'], 'İtalyan keşiş Arezzolu Guido (Guido d\'Arezzo), dört çizgili dizeği ve \'Ut queant laxis\' ilahisinden türettiği hece adlandırma sistemini geliştirerek modern notasyonun öncüsü olmuştur.'),
  ('Erken Orta Çağ el yazmalarında metnin üzerine çizilen ve ezginin yalnızca iniş-çıkış yönünü yaklaşık olarak hatırlatan işaretlere ne ad verilir?', 'Neuma', ['Talea', 'Clausula', 'Tablatur'], 'Dizek öncesi dönemde kullanılan neumalar, kesin ses yüksekliği veya süre belirtmekten ziyade şarkıcılara zaten bildikleri ezgi kıvrımlarını anımsatan grafik işaretlerdi.'),
  ('12. yüzyılda yaşamış, \'Ordo Virtutum\' adlı ahlak oyununu ve mistik ilahileri bestelemiş olan Alman başrahibe kimdir?', 'Hildegard von Bingen', ['Beatriz de Dia', 'Francesca Caccini', 'Kassia Konstantinopolitana'], 'Hildegard von Bingen, geniş ses aralıklı özgün monofonik ilahileri ve bilinen en eski ahlak dramlarından \'Ordo Virtutum\' ile Orta Çağ müzik tarihinin en önemli kadın bestecisidir.'),
  ('Paris\'teki Notre Dame Katedrali çevresinde 12. yüzyıl sonlarında gelişen erken çokseslilik (organum) okulunun iki öncü ustası hangi seçenekte birlikte verilmiştir?', 'Léonin ve Pérotin', ['Machaut ve Vitry', 'Binchois ve Dufay', 'Ockeghem ve Obrecht'], 'Notre Dame okulunun bilinen ilk büyük bestecisi iki sesli organumlarıyla Léonin, onu izleyerek üç ve dört sesli organumlar yazan ustası ise Pérotin\'dir.'),
  ('Katolik ayininin değişmez bölümlerini (Ordinarium Missae) tek bir bütün olarak dört sesli besteleyen ilk bilinen besteci ve eseri hangisidir?', 'Guillaume de Machaut – Messe de Nostre Dame', ['Pérotin – Sederunt principes', 'Francesco Landini – Ecco la primavera', 'Guillaume Dufay – Nuper rosarum flores'], '14. yüzyılın en büyük şair-bestecisi Guillaume de Machaut\'nun \'Messe de Nostre Dame\' adlı eseri, bir bestecinin elinden çıkmış ilk eksiksiz çoksesli ayin döngüsüdür.'),
  ('11. ve 13. yüzyıllar arasında Güney Fransa\'da (Provence) Oksitan dilinde saray aşkı (fin\'amors) temalı şarkılar üreten soylu şair-müzisyenlere ne ad verilirdi?', 'Troubadour', ['Trouvère', 'Meistersinger', 'Castrato'], 'Güney Fransa\'da Oksitanca (langue d\'oc) yazan ozanlara troubadour, Kuzey Fransa\'da Eski Fransızca (langue d\'oïl) yazanlara ise trouvère denirdi.'),
  ('Fransız troubadour geleneğinin Orta Çağ Almanya\'sındaki karşılığı olan ve şövalye idealine dayalı aşk şarkıları söyleyen ozan grubuna ne ad verilir?', 'Minnesänger', ['Stadtpfeifer', 'Goliard', 'Kapellmeister'], 'Almanca \'Minne\' (soylu aşk) sözcüğünden türeyen Minnesänger geleneği, Walther von der Vogelweide ve Wolfram von Eschenbach gibi ozanlarla 12–14. yüzyıllarda gelişmiştir.'),
  ('Orta Çağ\'da kendi şiirlerini yazan soylu ozanların aksine, kasaba kasaba dolaşarak başkalarının şarkılarını seslendiren, hokkabazlık ve çalgıcılık yapan gezgin göstericilere ne denirdi?', 'Jongleur', ['Kantor', 'Trouvère', 'Kapellmeister'], 'Jongleur\'ler (Almancada Gaukler/Spielmann), alt sınıftan gelen profesyonel gezgin icracılardı; daha sonra saray ve loncalarda yerleşik müzisyen olanlara \'ménestrel\' denmiştir.'),
  ('13. yüzyılda Bavyera\'daki Benediktbeuern Manastırı\'nda derlenen, gezgin öğrencilerin (goliard) içki, talih ve bahar konulu Latince-Almanca dünyevi şarkılarını içeren külliyat hangisidir?', 'Carmina Burana', ['Cantigas de Santa Maria', 'Liber Usualis', 'Codex Calixtinus'], 'Carmina Burana el yazması, gezgin din adamları ve üniversite öğrencilerinin (goliardlar) 11–13. yüzyıllarda yazdığı 200\'den fazla dünyevi ve hicivli şiir-şarkıyı içerir.'),
  ('Katolik cenaze ayinlerinde (Requiem) okunan ve Berlioz\'dan Liszt\'e pek çok romantik bestecinin de alıntıladığı ünlü Orta Çağ sekansı (sequentia) hangisidir?', 'Dies irae', ['Sumer is icumen in', 'Veni Creator Spiritus', 'Kalenda Maya'], '13. yüzyılda Celanolu Thomas\'a atfedilen \'Dies irae\' (Gazap Günü), Kıyamet Günü\'nü betimleyen en meşhur Gregoryen sekansıdır.'),
  ('Orta Çağ\'da kucağa ya da omuza konularak yayla çalınan, genellikle beş telli ve perde bağları olan, modern keman ailesinin uzak atalarından sayılan çalgı hangisidir?', 'Vielle', ['Bombarde', 'Sackbut', 'Virginal'], 'Vielle (Almancada Fidel), troubadour ve jongleur\'lerin şarkı eşliğinde en sık kullandığı yaylı Orta Çağ çalgısıdır.'),
  ('Orta Çağ minyatürlerinde müzisyenin sol eliyle küçük körüğünü pompalarken sağ eliyle tuşlarına bastığı, tören alaylarında taşınabilen küçük org türüne ne ad verilir?', 'Portatif org', ['Pozitif kilise orgu', 'Hidrolik su orgu', 'Pedallı katedral orgu'], 'Kayışla omuza asılarak taşınabilen tek sıralı borulu küçük orglara \'portatif org\', yere ya da masaya konulan daha büyük oda orglarına ise \'pozitif org\' denirdi.'),
  ('Gregoryen düz ezgilerinin derlenip standartlaştırılması geleneği hangi din adamının adıyla özdeşleşmiştir?', 'Papa I. Gregorius', ['Papa XXII. Ioannes', 'Aziz Hieronymus', 'Canterburyli Anselmus'], 'MS 590–604 yılları arasında görev yapan Büyük Papa I. Gregorius, Batı kilisesi litürjisini düzenlediği için bu ezgi külliyatı onun adıyla \'Gregoryen\' olarak anılmıştır.'),
  ('14. ile 16. yüzyıllar arasında Alman kentlerinde ayakkabıcı Hans Sachs gibi esnaf ve zanaatkârların lonca kurallarıyla sürdürdüğü şarkıcılık geleneğine ne ad verilir?', 'Meistersinger', ['Minnesänger', 'Trobairitz', 'Troubadour'], 'Soylu şövalyelerin Minnesang geleneği kentli burjuva ve zanaatkâr loncalarına geçtiğinde, sıkı yarışma kurallarına bağlı \'Meistersinger\' (Usta Şarkıcılar) geleneğine dönüşmüştür.'),
  ('Bir şövalyenin kırsalda koyun güden genç bir çoban kızla karşılaşmasını ve aralarındaki esprili diyaloğu konu alan Orta Çağ Fransız şarkı türü hangisidir?', 'Pastourelle', ['Chanson de geste', 'Kyriale', 'Magnificat'], 'Troubadour ve trouvère edebiyatında çok sevilen \'pastourelle\', atlı şövalye ile zeki çoban kız arasındaki kur yapma sahnelerini anlatısal biçimde işler.'),
  ('Orta Çağ\'da iki ucundan tutulan ahşap bir çerçeve içindeki tellerin parmaklarla çekildiği, özellikle İrlanda ve Britanya Adaları\'nda ozanların (bard) simgesi olan çalgı hangisidir?', 'Çerçeve arp', ['Lir gövdeli krwth', 'Çift borulu aulos', 'Perdeli viola da braccio'], 'Üçgen çerçeveli Gotik ve Kelt arpi (İskoç-İrlanda geleneğinde clàrsach), Orta Çağ ozanlarının destan ve lirik şiir eşliğinde kullandığı en saygın telli çalgılardandı.'),
  ('Rönesans müziğinde hiçbir çalgı eşliği olmaksızın yalnızca insan seslerinden oluşan koro düzenini tanımlamak için kullanılan İtalyanca terim hangisidir?', 'A cappella', ['Concertato', 'Obbligato', 'Pizzicato'], '\'Şapel üslubunda\' anlamına gelen \'a cappella\', özellikle Roma\'daki Sistina Şapeli korosunun çalgısız çoksesli icra geleneğinden doğmuş bir terimdir.'),
  ('Rönesans çoksesliliğinde bir sesin başlattığı ezgisel motifin kısa bir süre sonra diğer sesler tarafından aynı ya da farklı perdeden taklit edilerek devralınmasına ne ad verilir?', 'Taklitli (imitatif) polifoni', ['Monofonik düz ezgi', 'Eş ritimli (homoritmik) akor dokusu', 'Sürekli bas doğaçlaması'], 'Josquin ve çağdaşlarıyla zirveye ulaşan taklitli polifoni, tüm ses partilerine eşit ezgisel önem kazandıran Rönesans\'ın en tipik doku tekniğidir.'),
  ('Rönesans vokal müziğinde şiirde \'yükselmek\' kelimesi geçtiğinde ezginin tizleşmesi, \'iç çekmek\' dendiğinde kısa suslarla bölünmesi gibi metni doğrudan betimleyen tekniğe ne ad verilir?', 'Kelime boyama', ['İzoritmik kurgu', 'Fauxbourdon yürüyüşü', 'Kırık akor eşliği'], 'Kelime boyama (word painting / madrigalism), metindeki imgelerin müzikal figürlerle somut biçimde resmedilmesi olup özellikle 16. yüzyıl madrigalinde zirveye çıkmıştır.'),
  ('Trento Konsili sürecinde çoksesli müziğin de kutsal sözleri berrakça duyurabileceğini kanıtladığı rivayet edilen \'Missa Papae Marcelli\' adlı eserin bestecisi kimdir?', 'Giovanni Pierluigi da Palestrina', ['Orlando di Lasso', 'Tomás Luis de Victoria', 'William Byrd'], 'Roma Okulu\'nun baş ustası Palestrina, altı sesli \'Missa Papae Marcelli\' ile dengeli kontrpuan ve metin anlaşılırlığını kusursuzca kaynaştırmıştır.'),
  ('1517\'de başlattığı Protestan Reformu\'nda cemaatin ibadete bizzat katılabilmesi için Almanca ilahiler (koraller) yazan ve \'Ein feste Burg ist unser Gott\'u besteleyen din adamı kimdir?', 'Martin Luther', ['Jean Calvin', 'Huldrych Zwingli', 'Ignatius Loyola'], 'Kendisi de iyi bir lavtacı ve flütçü olan Martin Luther, müziği teolojinin hemen yanına koymuş ve cemaatin kendi dilinde söylediği Protestan koral geleneğini başlatmıştır.'),
  ('16. yüzyıl İtalya\'sında Petrarca ve Tasso gibi şairlerin aşk, doğa ve ölüm konulu seçkin şiirleri üzerine bestelenen, eşliksiz dört-altı sesli en önemli dünyevi vokal form hangisidir?', 'Madrigal', ['Motet', 'Oratoryo', 'Koral'], 'Rönesans İtalyan madrigali, her dizeye yeni müzik üretilen (through-composed), zengin kelime boyamaları içeren aristokratik ve duygu yüklü dünyevi çoksesli formdur.'),
  ('Venedik\'teki San Marco Bazilikası\'nın karşılıklı iki org balkonu mimarisinden yararlanarak birbirine yankılı biçimde seslenen bölünmüş korolar (\'cori spezzati\') geleneğini hangi okul geliştirmiştir?', 'Venedik Okulu', ['Notre Dame Okulu', 'Burgondiya Okulu', 'Mannheim Okulu'], 'Adrian Willaert\'in başlattığı ve Andrea ile Giovanni Gabrieli\'nin zirveye taşıdığı Venedik Okulu, mekânsal çok korolu (polikoral) görkemiyle Barok concertato üslubunu müjdelemiştir.'),
  ('Melankoli estetiğini yansıtan \'Flow, my tears\' şarkısını ve bunun yedi pavane\'dan oluşan \'Lachrimae\' çalgısal uyarlamasını yazan İngiliz lavta virtüözü kimdir?', 'John Dowland', ['John Bull', 'Thomas Campion', 'Robert Johnson'], '\'Semper Dowland, semper dolens\' (Daima Dowland, daima kederli) sözüyle özdeşleşen John Dowland, Rönesans sonu İngiliz lavta şarkısının (lute ayre) en büyük ustasıdır.'),
  ('Rönesans\'ta telli ve klavyeli çalgılar için ses perdelerini dizek üzerindeki notalar yerine parmakların basacağı tel ve perde numaralarıyla gösteren pratik yazı sistemine ne ad verilir?', 'Tablatur', ['Neuma', 'Kare notasyon', 'Şifreli bas'], 'Lavta, vihuela ve org için yaygın kullanılan tablatur sisteminde müzik, soyut ses yüksekliği yerine icracının elini nereye koyacağını gösteren harf veya rakamlarla yazılırdı.'),
  ('Josquin des Prez\'nin cırcır böceğinin yaz sıcağında durmaksızın ötüşünü kıvrak ritmik tekrarlarla betimlediği neşeli İtalyanca frottola\'sı hangisidir?', 'El Grillo', ['Il bianco e dolce cigno', 'La Guerre', 'Ecco mormorar l\'onde'], '\'El grillo è buon cantore\' (Cırcır böceği iyi bir şarkıcıdır) dizeleriyle başlayan bu nüktedan eser, Josquin\'in mizahi ve dünyevi cephesinin en sevilen örneğidir.'),
  ('Rönesans dönemi koro topluluklarında kadınların kilise korolarında şarkı söylemesine izin verilmediği için soprano ve alto partileri genellikle kimler tarafından seslendirilirdi?', 'Erkek çocuk sopranolar ve falsetto tekniği kullanan yetişkin erkekler tarafından', ['Perdenin arkasına gizlenen profesyonel kadın opera sanatçıları tarafından', 'Yalnızca tiz blokflüt ve rebec çalan gezgin çalgıcılar tarafından', 'Ses telleri kalınlaştırılmış yaşlı keşişlerden oluşan bas korosu tarafından'], 'Papa\'nın \'mulieres in ecclesia taceant\' ilkesi uyarınca kilise korolarında üst partileri eğitimli erkek çocuklar (boy sopranos), falsettistler (kontrtenorlar) ve 16. yüzyıl sonundan itibaren kastratolar okurdu.'),
  ('Rönesans döneminde halka açık ticari konser salonları henüz var olmadığından dünyevi çoksesli müzik (madrigal, şanson, konsort müziği) ağırlıklı olarak hangi ortamda icra edilirdi?', 'Soylu saraylarında ve eğitimli burjuva evlerinde amatör müzikseverlerin kendi aralarında toplanarak söylemesiyle', ['Binlerce biletli izleyicinin doldurduğu büyük belediye amfitiyatrolarında', 'Yalnızca manastır hücrelerinde sessizlik yemini etmiş keşişlerin mırıldanmasıyla', 'Üniversite stadyumlarında düzenlenen uluslararası koro olimpiyatlarında'], 'Matbaanın yaygınlaşmasıyla Rönesans\'ta nota okuryazarlığı görgülü eğitimin parçası sayılmış (Castiglione\'nin Saraylı Kitabı); madrigal ve şansonlar masa başında bizzat katılımcıların zevki için söylenmiştir.'),
  ('Barok dönemin en yaygın klavyeli çalgılarından klavsende (harpsichord) telden ses elde etme düzeneği nasıl çalışır?', 'Tuşa bağlı dikey ahşap dildeki (jack) küçük mızrabın teli çekmesiyle', ['Keçe kaplı ahşap çekiçlerin tellere alttan hızla çarpmasıyla', 'Pirinç levhaların telleri ortadan bölerek sürekli bastırmasıyla', 'Körükten gelen basınçlı havanın metal dilleri titreştirmesiyle'], 'Klavsende (çembalo) tuşa basıldığında yükselen \'jack\' adlı ahşap parça üzerindeki kuş tüyü veya deri mızrap (plectrum) teli çeker.'),
  ('Tuşun arka ucundaki pirinç bir dilin (tangent) tele alttan vurup tuş basılı tutulduğu sürece teli hem böldüğü hem de titreştirdiği son derece narin sesli klavyeli çalgı hangisidir?', 'Klavikord', ['Spinet', 'Regal', 'Çelesta'], 'Klavikordda metal \'tangent\' teli terk etmez; bu sayede icracı hem tuş vuruşuyla hafif gürlük nüansı hem de parmak sallamayla vibrato üretebilir.'),
  ('Yaklaşık 1700 yılında Floransa\'daki Medici sarayında klavsenin mızrap düzeneği yerine tellere vurup hemen geri çekilen çekiç mekanizmasını icat ederek ilk piyanoyu yapan usta kimdir?', 'Bartolomeo Cristofori', ['Gottfried Silbermann', 'Adolphe Sax', 'Johann Andreas Stein'], 'Medici Prensi Ferdinando\'nun çalgı koruyucusu Bartolomeo Cristofori, \'gravicembalo col piano e forte\' (hem hafif hem gür çalabilen klavsen) adlı icadıyla modern piyanonun babası olmuştur.'),
  ('Rönesans ve Barok dönemlerin gözde çalgısı lavtanın (lute) fiziksel yapısına ilişkin aşağıdaki ifadelerden hangisi doğrudur?', 'Armut biçimli dilimli sırtı, geriye doğru dik açıyla kırık burgu kutusu ve çiftli bağırsak telleri vardır', ['Düz arka kapağı, çelikten tekli dört teli ve keman gibi omuza dayanan çeneliği vardır', 'Sekizgen deri kaplı gövdesi, metal perdeleri ve at kılından yapılmış kısa bir yayı vardır', 'Boydan boya pirinç döküm ses kutusu ve mızrap yerine keçe tokmakları vardır'], 'İslam dünyasındaki \'el-ud\'dan türeyen Avrupa lavtası; dilimli derin ahşap sırtı, sapta bağırsak perde bağları, geriye kıvrık burgu kutusu ve \'course\' denilen çiftli tel gruplarıyla tanınır.'),
  ('16. yüzyıl ortasından 18. yüzyıl ortasına dek Kuzey İtalya\'da Amati, Stradivari ve Guarneri ailelerinin yaylı çalgı yapımcılığını dünya zirvesine taşıdığı şehir hangisidir?', 'Cremona', ['Bologna', 'Napoli', 'Palermo'], 'Andrea Amati\'nin kurduğu, Niccolò Amati\'nin geliştirdiği, Antonio Stradivari ve Giuseppe Guarneri \'del Gesù\'nun taçlandırdığı Cremona okulu, keman yapımcılığının altın merkezidir.'),
  ('Barok orkestrada doğal trompet ikilisi veya üçlüsünün neredeyse ayrılmaz ritmik ve armonik eşlikçisi olarak tonik ve dominant seslerine akortlanan vurmalı çalgı hangisidir?', 'Çift kazanlı timpani', ['Üçgen', 'Ksilofon', 'Büyük bas davul'], 'Bakır kazanlar üzerine gerilmiş buzağı derisi ve ahşap başlıklı tokmaklarla çalınan Barok timpani, trompet grubunun bas partisi gibi işlev görerek görkemli şölen ve zafer atmosferi yaratırdı.'),
  ('Antonio Vivaldi\'nin iki konçerto besteleyerek konser sahnesine taşıdığı, armut biçimli gövdesi ve parmakla/mızrapla çekilen bağırsak veya metal telleriyle Kuzey İtalya\'da gelişen çalgı hangisidir?', 'Mandolin', ['Balalayka', 'Ukulele', 'Buzuki'], 'Küçük lavtadan (mandola) türeyen mandolin, Vivaldi\'nin Do majör tek mandolin ve Sol majör çift mandolin konçertolarıyla Barok solo dağarcığında ölümsüz bir yer edinmiştir.'),
  ('Barok çalgı dağarcığında yaylı çalgıların köprüsüne takılan ahşap veya kurşun tarak biçimli küçük parçanın (\'sordino\' / susturucu) sese etkisi nedir?', 'Köprü titreşimini kısıtlayarak ses gürlüğünü düşürmek ve buğulu, içe dönük gümüşsü bir tını rengi yaratmak', ['Telleri bir oktav tizleştirerek kemanı pikolo kemana dönüştürmek', 'Yay sürtünmesini artırarak bakır üflemelilerden daha gür bir ses çıkarmak', 'Bağırsak tellerin nemden kopmasını engelleyen koruyucu kalkan olmak'], 'Lully, Purcell ve Vivaldi gibi Barok besteciler uyku, rüya, cenaze veya doğaüstü fısıltı sahnelerinde yaylılara \'con sordino\' ibaresiyle susturucu taktırarak büyüleyici bir renk değişimi elde etmiştir.'),
  ('Barok orkestrada sürekli bas (basso continuo) grubunu oluşturmak için en sık bir araya getirilen standart çalgı eşleşmesi aşağıdakilerden hangisidir?', 'Bas çizgisini tutan çello veya fagot ile akorları dolduran klavsen, org veya theorbo', ['Tiz ezgiyi çalan iki pikolo flüt ile ritim tutan üçgen ve tef', 'Valfli korno dörtlüsü ile çelik telli elektro-akustik arp', 'Eşliksiz insan sesleri korosu ile su dolu cam bardaklar'], 'Sürekli bas tek bir çalgı değil işlevsel bir ikilidir: pes melodik çizgiyi uzatan bir çalgı (viyolonsel, gamba, fagot) ile şifreli akorları doğaçlayan çoksesli bir çalgı (klavsen, org, lavta/theorbo) birlikte çalar.'),
  ('Barok dönemde kullanılan keman ve lavta gibi çalgılarda \'bağırsak tel\' (catgut) adı verilen tellerin gerçek hammaddesi neydi?', 'Koyun veya kuzu ince bağırsağının temizlenip şeritler halinde bükülerek kurutulmuş lifleri', ['Sokak kedilerinin bıyık ve kuyruk kıllarının balmumuyla örülmesi', 'At yelesi kıllarının eritilmiş çam reçinesiyle sıkıştırılması', 'İpek böceği kozasının bakır tozuyla kaynatılmış iplikleri'], 'İngilizce \'catgut\' adına karşın bu tellerin kediyle hiçbir ilgisi yoktur; yüzyıllar boyunca en kaliteli çalgı telleri koyun/kuzu bağırsağından (özellikle İtalya\'da Roma ve Abruzzo\'da) üretilmiştir.'),
  ('1600–1750 yılları arasındaki sanat ve müzik çağını adlandırmak için kullanılan \'Barok\' teriminin etimolojik kökeni hangi anlama dayanır?', 'Portekizcede düzgün küre biçiminde olmayan biçimsiz inciye verilen \'barroco\' adına', ['Latincede kusursuz simetrik mermer sütun anlamına gelen mimari terime', 'İtalyancada ilkbahar çiçeklerinin yeniden açmasını anlatan şiirsel ifadeye', 'Almancada kilise çanlarının aynı anda çalınmasını belirten lonca sözcüğüne'], 'Başlangıçta 18. yüzyıl Aydınlanma eleştirmenlerince aşırı süslü ve abartılı bulunarak Portekizce \'barroco\' (yamuk/biçimsiz inci) sözcüğüyle küçümsenen dönem, sonradan tarafsız bir tarih terimine dönüşmüştür.'),
  ('Barok müzikte kademeli gürleşme (crescendo) ve azalma (diminuendo) yerine ses şiddetinin \'forte\' ve \'piano\' blokları halinde aniden değişmesine ne ad verilir?', 'Teraslı dinamik', ['Rubato hız esnekliği', 'Kromatik modülasyon', 'Eşit tampere ses düzeni'], 'Klavsen ve orgun mekanik doğası ile concertino-ripieno nöbetleşmesinden kaynaklanan keskin güçlü/hafif karşıtlıkları \'teraslı dinamik\' (terraced dynamics) olarak adlandırılır.'),
  ('Barok partisyonlarda en alt dizekteki bas notalarının altına veya üstüne yazılan \'6\', \'6/4\', \'7\' ve \'#\' gibi rakam ve işaretlerin bulunduğu sisteme ne ad verilir?', 'Şifreli bas', ['Mensural oran yazısı', 'Lavta tablaturu', 'Solfej heksakordu'], 'Sürekli bas (basso continuo) uygulamasında klavsen, org veya theorbo icracısı, bas notasının altındaki bu rakam şifrelerine bakarak hangi akor çevrimini doğaçlayacağını anlar.'),
  ('Barok dönemin en gelişmiş taklitli kontrpuan formu olan \'füg\'de, eserin en başında tek bir ses partisi tarafından eşliksiz duyurulan ana temaya ne ad verilir?', 'Özne', ['Ritornello nakaratı', 'Basso ostinato', 'Coda kapanışı'], 'Füg formunun tüm yapı taşını oluşturan ve birinci ses tarafından eksen tonda sunulan açılış temasına \'özne\' (Latince dux – önder) adı verilir.'),
  ('Fügden farklı olarak birinci sesin başlattığı bütün ezgi çizgisinin başından sonuna dek diğer sesler tarafından nota nota kusursuz bir kopya halinde gecikmeli izlendiği en katı taklit formu hangisidir?', 'Kanon', ['Ricercar', 'Canzona', 'Sinfonia'], 'Her kanon taklitlidir ancak fügde sesler serim sonrası özgürleşirken, kanonda takip eden ses (comes) öncü sesi (dux) eserin sonuna dek katı bir yasayla (\'kanon\' = kural/yasa) izler.'),
  ('Alman Barok bestecisi Johann Pachelbel\'in dünyaca ünlü \'Re Majör Kanon\'unun yapısal kurgusu aşağıdakilerden hangisinde doğru tanımlanmıştır?', 'İki ölçülük sabit bir bas yürüyüşü (ground bass) üzerinde üç kemanın tam üç sesli kanon ve yirmi sekiz çeşitleme örmesi', ['Büyük bir senfoni orkestrası ve koro için dört bölümlü fırtına senfonisi olarak yazılması', 'Solo klavsen için on iki farklı majör tonda füg dizisi biçiminde tasarlanması', 'İki trompet ve timpaninin karşılıklı savaş çağrılarıyla ilerleyen açık hava süiti olması'], 'Asıl adı \'Üç Keman ve Sürekli Bas için Kanon ve Gigue\' olan eserde çello/continuo sekiz notalık bir \'basso ostinato\'yu 28 kez tekrarlarken üstteki üç keman kusursuz bir kanon sergiler.'),
  ('En alt partide kısa ve değişmez bir ezgi-armoni kalıbının eser boyunca inatla tekrarlanması üzerine üst seslerin sürekli yeni çeşitlemeler dokuduğu Barok tekniğin genel adı nedir?', 'Basso ostinato', ['Stile concitato', 'Recitativo secco', 'Cori spezzati'], 'İtalyanca \'inatçı bas\' anlamına gelen basso ostinato (İngilizcede ground bass), Barok dönemde hem derin ağıtlarda hem de görkemli çalgısal çeşitlemelerde temel yapı taşı olmuştur.'),
  ('Barok dönemin gözde orkestra türü \'konçerto grosso\'da karşılıklı diyalog kuran küçük solist topluluğu ile büyük orkestra gövdesine sırasıyla hangi adlar verilir?', 'Concertino ve Ripieno', ['Dux ve Comes', 'Cantus ve Tenor', 'Soli ve Cadenza'], 'Corelli ve Handel\'in konçerto grosso\'larında çoğunlukla iki keman ve bir çellodan oluşan küçük solist gruba \'concertino\', ‘dolduran’ anlamındaki tam orkestraya ise \'ripieno\' (veya tutti) denir.'),
  ('Klasik dönem senfonisinin ve konçertosunun dört veya üç bölümlü yapısına da zemin hazırlayan standart İtalyan Barok solo konçertosunun bölüm tempoları sıralaması nasıldır?', 'Hızlı – Yavaş – Hızlı', ['Yavaş – Hızlı – Yavaş – Hızlı', 'Ağır Marş – Menuet – Füg', 'Çok Yavaş – Orta – Çok Yavaş'], 'Torelli, Albinoni ve özellikle Vivaldi ile yerleşen üç bölümlü İtalyan konçertosu (Allegro – Adagio/Largo – Allegro) enerjik iki dış bölüm arasına şarkısal ve lirik bir orta bölüm yerleştirir.'),
  ('Barok \'süit\' (Almanya\'da Partita, Fransa\'da Ordre) formunun temel tanımı ve ton düzeni aşağıdakilerden hangisidir?', 'Farklı ulusal kökenli ve karşıt tempolu stilize dans bölümlerinin genellikle aynı eksen tonda art arda dizildiği çok bölümlü çalgı eseri', ['Her bölümü yarım ton tizleşerek on iki farklı tonda ilerleyen kesintisiz opera sahnesi', 'Kutsal Kitap\'tan alınan ayetlerin koro ve solistlerce sahnesiz anlatıldığı dini dram', 'Tek bir kısa temanın hiçbir ritim değişikliği olmadan kırk kez tekrarlandığı kanon'], 'Barok süit, artık gerçekten dans edilmek için değil dinlenmek için inceltilmiş (stilize) ulusal dansların ortak ton merkezinde (bazen minör/majör karşıtlığıyla) birleştiği formdur.'),
  ('17. yüzyıl sonunda Johann Jakob Froberger\'in katkısıyla standartlaşan klasik Barok süitin dört temel çekirdek dansının doğru sıralanışı hangisidir?', 'Allemande – Courante – Sarabande – Gigue', ['Pavane – Galliard – Minuet – Polonez', 'Prelüd – Gavotte – Bourrée – Badinerie', 'Sinfonia – Siciliana – Rigaudon – Chaconne'], 'Olgun Barok süitin omurgasını Alman (Allemande), Fransız/İtalyan (Courante), İspanyol (Sarabande) ve İngiliz-İrlanda (Gigue) kökenli bu dört dans oluşturur.'),
  ('Barok opera, oratoryo ve pasyonlarda olay örgüsünü hızla ilerleten diyalogların yalnızca klavsen/org ve çello (sürekli bas) eşliğinde konuşma ritmine yakın seslendirildiği türe ne ad verilir?', 'Kuru resitatif (Recitativo secco)', ['Eşlikli resitatif (Recitativo accompagnato)', 'Da capo arya', 'Koral füg'], 'Sahnede aksiyonu ve karşılıklı konuşmayı taşıyan \'recitativo secco\', yalnızca sürekli basın kısa akor dokunuşlarıyla desteklenir; yoğun dramatik kriz anlarında ise tüm yaylı orkestranın katıldığı \'recitativo accompagnato\'ya geçilir.'),
  ('Barok dönemde \'oratoryo\' ile \'opera\' türleri karşılaştırıldığında her ikisinde de arya, resitatif, düet, koro ve orkestra bulunmasına karşın oratoryoyu operadan ayıran temel özellik nedir?', 'Sahne dekoru, kostüm ve tiyatro oyunculuğu olmadan çoğunlukla kutsal veya ahlaki öyküleri anlatıcı (testo/historicis) yardımıyla sunması', ['Oratoryoda hiçbir kadın veya tiz sesin yer almayıp yalnız bas korosunun bulunması', 'Oratoryonun yalnızca on dakikalık tek bölümlü dans müziklerinden oluşması', 'Operada Latince zorunluyken oratoryonun yalnızca Fransız saray lehçesiyle yazılması'], 'Roma\'da kiliselerin dua salonlarında (oratorio) özellikle operaların yasaklandığı Büyük Perhiz (Lent) döneminde gelişen oratoryo, kostümsüz ve sahnesiz dramatik kutsal müzik türüdür.'),
  ('Barok dönemde İsa\'nın Son Akşam Yemeği\'nden çarmıha gerilişine dek çektiği acıları İncil metinlerine (Matta, Yuhanna, Luka, Markos) dayanarak solistler, İncil anlatıcısı (Evangelist), koro ve orkestrayla canlandıran büyük form hangisidir?', 'Pasyon', ['Magnificat', 'Te Deum', 'Stabat Mater'], 'Kutsal Hafta\'da (özellikle Kutsal Cuma günü) seslendirilen \'Pasyon\', İncil metnini okuyan tenor Evangelist, İsa/Pilatus solistleri, halkı simgeleyen \'turba\' koroları ve tefekkür aryalarıyla Barok dramatik dini müziğin zirvesidir.'),
  ('Barok dönemde hem dünyevi oda müziği (solo ses ve continuo için aşk öyküsü) hem de Lutherci kilise müziği (koro, solistler ve orkestra için haftalık İncil yorumu) olarak yüzlerce örneği verilen çok bölümlü vokal tür hangisidir?', 'Kantat', ['Missa', 'Madrigal', 'Conductus'], 'İtalyanca \'cantare\' (şarkı söylemek; çalgı için \'sonata\'nın karşıtı) kökünden gelen kantat, İtalya\'da Carissimi ve Scarlatti ile lirik oda formuna, Almanya\'da ise Bach ve Telemann ile kilise ibadetinin merkezine dönüşmüştür.'),
  ('Barok klavye ve yaylı notasyonunda notaların üzerine konulan kanca, zikzak ve küçük artı gibi semboller (mordent, tril, grupetto, apojatür) icracıya neyi bildirir?', 'Ana notayı komşu seslerle kıvrak biçimde bezeyen üslupsal süslemeleri', ['Yaylı çalgıcıların yaylarını bırakıp ayağa kalkarak selam vermesini', 'O ölçünün tamamen atlanarak bir sonraki sayfaya geçilmesini', 'Orgun rüzgâr körüğünün kapatılarak basıncın düşürülmesini'], 'Özellikle Fransız klavsen okulunda (Couperin\'in ayrıntılı süsleme tablosu) ve Bach\'ta trillerin üst komşu sesten başlaması ve apojatürlerin vurgulu düşmesi gibi \'süslemeler\' yüzeysel ek değil ifadenin özüdür.'),
  ('1570\'lerin sonlarında Floransa\'da Kont Giovanni de\' Bardi\'nin sarayında toplanarak Antik Yunan trajedilerinin müzikle nasıl seslendirildiğini tartışan ve operanın doğuşuna öncülük eden aydınlar topluluğuna ne ad verilir?', 'Floransa Camerata\'sı', ['Venedik San Marco Şapeli Okulu', 'Roma Papalık Sistina Korosu Birliği', 'Napoli Kraliyet Konservatuvarı Loncası'], 'Vincenzo Galilei, Giulio Caccini ve Jacopo Peri gibi hümanist müzisyen ve şairleri buluşturan Floransa Camerata\'sı, ağır polifoni yerine sözü anlaşılır kılan \'stile rappresentativo\' ve monodiyi geliştirmiştir.'),
  ('1598\'de bestelenen \'Dafne\'nin büyük bölümü kaybolduğu için müzik tarihine \'günümüze eksiksiz ulaşan en eski opera\' olarak geçen ve 1600\'de Floransa\'da IV. Henri ile Maria de\' Medici\'nin düğününde sahnelenen Jacopo Peri eseri hangisidir?', 'Euridice', ['La liberazione di Ruggiero', 'Il ritorno d\'Ulisse in patria', 'La serva padrona intermezzosu'], 'Ottavio Rinuccini\'nin librettosu üzerine Jacopo Peri\'nin (bazı bölümlerinde Giulio Caccini katkısıyla) bestelediği 1600 tarihli \'Euridice\', notası tam olarak korunan ilk operadır.'),
  ('1607 yılında Mantova\'daki Gonzaga Sarayı\'nda sahnelenen ve zengin orkestra renkleri, çarpıcı armonileri ve dramatik gücüyle opera tarihinin ilk büyük başyapıtı kabul edilen Claudio Monteverdi eseri hangisidir?', 'L\'Orfeo', ['Dido ve Aeneas trajedisi', 'Julius Caesar Mısır\'da operası', 'Hippolyte ve Aricie lirik trajedisi'], 'Alessandro Striggio\'nun librettosu üzerine yazılan Monteverdi\'nin \'L\'Orfeo\'su (Favola in musica), kırktan fazla çalgılık renkli orkestrası ve \'Possente spirto\' aryasıyla yeni türü sanatsal olgunluğa ulaştırmıştır.'),
  ('Operanın saray soylularının özel düğün eğlencesi olmaktan çıkıp bilet satın alan herkesin izleyebildiği ticari bir halk sanatına dönüşmesi 1637\'de hangi şehirde açılan Teatro San Cassiano ile gerçekleşmiştir?', 'Venedik', ['Floransa Dükalık Merkezi', 'Viyana İmparatorluk Başkenti', 'Paris Kraliyet Akademisi'], '1637 Venedik Karnavalı\'nda açılan San Cassiano Tiyatrosu dünyanın ilk halka açık biletli opera evidir; bu ticari model büyük korolar yerine yıldız solistleri ve çarpıcı sahne makinelerini öne çıkarmıştır.'),
  ('Vatikan\'daki Sistina Şapeli\'nde Kutsal Hafta\'da seslendirilen, notasının dışarı çıkarılması Papa tarafından aforoz cezasıyla yasaklandığı halde on dört yaşındaki Mozart\'ın bir kez dinleyip ezberden kağıda döktüğü dokuz sesli \'Miserere\' kimin eseridir?', 'Gregorio Allegri', ['Giovanni Gabrieli', 'Carlo Gesualdo', 'Arcangelo Corelli'], 'Yaklaşık 1638\'de Gregorio Allegri tarafından Mezmur 51 üzerine yazılan eşliksiz \'Miserere mei, Deus\', küçük koronun efsanevi tiz Do (C6) doğaçlama süslemesiyle Sistina Şapeli\'nin gizli hazinesi sayılmıştır.'),
  ('Hiç vokal eser veya opera yazmayıp yalnızca yaylı çalgı müziğine odaklanan; Op. 1–4 trio sonatları, Op. 5 keman sonatları ve Op. 6 konçerto grosso\'larıyla tüm Avrupa\'da \'klasik denge ve asalet\' modeli sayılan besteci kimdir?', 'Arcangelo Corelli', ['Claudio Monteverdi', 'Alessandro Scarlatti', 'Giovanni Battista Pergolesi'], 'Roma\'da Kardinal Ottoboni\'nin himayesinde çalışan kemancı-besteci Arcangelo Corelli (1653–1713), yalnızca altı opus yayımlamasına karşın işlevsel tonalitenin ve Barok yaylı yazısının kurucu ustası olmuştur.'),
  ('Kızıl saçları ve katolik rahiplik unvanı nedeniyle Venedik\'te \'Il Prete Rosso\' (Kızıl Rahip) lakabıyla tanınan ve beş yüzün üzerinde konçerto besteleyen Barok virtüöz kimdir?', 'Antonio Vivaldi', ['Domenico Scarlatti', 'Jean-Baptiste Lully', 'Georg Philipp Telemann'], '1703\'te rahip takdis edilen Antonio Vivaldi (1678–1741), göğüs darlığı (astım benzeri rahatsızlığı) nedeniyle ayin yönetmekten muaf tutulmuş ve yaşamını keman ile besteciliğe adamıştır.'),
  ('Vivaldi\'nin 1725\'te yayımlanan \'Il cimento dell\'armonia e dell\'inventione\' (Armoni ve Buluş Arasındaki Yarışma, Op. 8) başlıklı on iki konçertoluk dizisinin ilk dört eseri hangi adla tüm zamanların en ünlü programlı Barok müziği olmuştur?', 'Dört Mevsim', ['Elementler Senfonisi', 'Brandenburg Konçertoları', 'Su Müziği Süitleri'], 'Op. 8\'in ilk dört keman konçertosu olan \'Le quattro stagioni\' (İlkbahar, Yaz, Sonbahar, Kış), doğa olaylarını ve köy yaşamını parlak keman efektleriyle betimleyen programlı müziğin başyapıtıdır.'),
  ('Vivaldi yalnızca yaylı konçertolarıyla değil, Ospedale della Pietà kızlar korosu ve orkestrası için Re majör tonda bestelediği hangi görkemli on iki bölümlük kutsal eseriyle (RV 589) koro dağarcığında ölümsüzleşmiştir?', 'Gloria', ['Yaratılış Oratoryosu', 'Büyük Si Minör Ayin', 'Alman Requiem\'i'], 'Parlak trompet-obua açılışı, lirik \'Domine Deus\' sopranosu ve \'Cum Sancto Spiritu\' fügüyle Vivaldi\'nin Re majör Gloria\'sı (RV 589), 20. yüzyıldaki yeniden keşfinden beri en sevilen Barok koro eseridir.'),
  ('Alessandro Scarlatti ve J. S. Bach ile aynı yıl (1685\'te!) doğan, Portekiz Prensesi ve İspanya Kraliçesi Maria Barbara\'nın müzik öğretmeni olarak Madrid\'e yerleşip \'555 tek bölümlük klavsen sonatı\' yazan dahi besteci kimdir?', 'Domenico Scarlatti', ['Antonio Soler', 'Baldassare Galuppi', 'Bernardo Pasquini'], '1685 yılı müzik tarihinde üç devin (J. S. Bach, G. F. Handel ve Domenico Scarlatti) ortak doğum yılıdır; Domenico Scarlatti yaşamının son yirmi sekiz yılını İber Yarımadası\'nda geçirerek klavsen sanatında devrim yapmıştır.'),
  ('18. yüzyıl Barok operasında erkek çocukların ergenlik öncesinde geçirdiği cerrahi müdahaleyle çocuksu tiz ses aralığını korurken yetişkin erkek akciğer kapasitesine ulaştığı yıldız şarkıcı tipine ve bu türün en ünlü temsilcisi Carlo Broschi\'nin sahne adına ne denirdi?', 'Kastrato – Farinelli', ['Kontrtenor – Senesino', 'Heldentenor – Nicolini', 'Basso profondo – Caffarelli'], 'Barok \'opera seria\'da mitolojik ve tarihi erkek kahramanları (Sezar, İskender) doğaüstü nefes uzunluğu ve koloratur gücüyle \'castrato\' şarkıcılar canlandırırdı; Carlo Broschi yani \'Farinelli\' (1705–1782) bu geleneğin en efsanevi yıldızıydı.'),
  ('Floransa\'da \'Giovanni Battista Lulli\' adıyla doğup çocuk yaşta Fransa\'ya giderek \'Güneş Kral\' XIV. Louis\'nin saray başmüzisyeni olan ve kraliyet ayrıcalığıyla Fransız operası üzerinde mutlak tekel kuran besteci kimdir?', 'Jean-Baptiste Lully', ['Marc-Antoine Charpentier', 'Jean-Philippe Rameau', 'François Couperin'], 'Kral XIV. Louis ile gençliğinde saray balelerinde yan yana dans eden Lully (1632–1687), Académie Royale de Musique\'in yönetimini devralarak bütün Fransa\'da kendisinden izinsiz sahne müziği yapılmasını yasaklatmıştır.'),
  ('Jean-Baptiste Lully\'nin 1687 yılında, Kral XIV. Louis\'nin hastalıktan kurtuluşunu kutlamak için yönettiği \'Te Deum\' provası sırasında meydana gelen ve ölümüne yol açan ünlü kaza nasıl gerçekleşmiştir?', 'Tempoyu tutmak için yere vurduğu ağır metal uçlu yönetim asasını kendi ayak parmağına saplayarak kangren olmasıyla', ['Sahne tavanından sarkan dev bulut makinesinin halatının kopup üzerine düşmesiyle', 'Orkestra çukurundaki mumların perdeleri tutuşturması sonucu dumandan zehirlenmesiyle', 'Saray bahçesindeki Su Müziği konseri sırasında kraliyet teknesinden nehre düşmesiyle'], 'Modern küçük baget yerine tempoyu sesli tutmak için ağır ve uzun bir asa (\'bâton de direction\') kullanan Lully, asayı ayağına vurmuş; dansçı olduğu için parmağının kesilmesini reddedince yayılan enfeksiyondan hayatını kaybetmiştir.'),
  ('İlk operasını elli yaşına gelene dek yazmayan ancak 1722\'de yayımladığı \'Traité de l\'harmonie\' (Armoni İncelemesi) adlı eseriyle modern akor kuramının, akor çevrimlerinin ve işlevsel armoninin bilimsel temelini atan Fransız Barok besteci kimdir?', 'Jean-Philippe Rameau', ['Gioseffo Zarlino', 'Guido d\'Arezzo', 'Philippe de Vitry'], 'Jean-Philippe Rameau (1683–1764), doğuşkanlar fiziğinden yola çıkarak örneğin Do–Mi–Sol ile Mi–Sol–Do\'nun ayrı akorlar değil aynı \'temel bas\'ın (basse fondamentale) çevrimleri olduğunu ilk kez kanıtlamıştır.'),
  ('Otuz altı yıllık kısa yaşamına karşın İngiliz müziğinin tartışmasız Barok dehası sayılan ve ölümünden sonra yayımlanan şarkı derlemesinde \'Orpheus Britannicus\' (Britanya\'nın Orfeus\'u) unvanıyla onurlandırılan besteci kimdir?', 'Henry Purcell', ['John Dowland', 'Thomas Morley', 'John Dunstable'], 'Henry Purcell (1659–1695), Fransız uvertür ritimlerini ve İtalyan sonat-arya lirizmini İngiliz dilinin doğal vurgu kıvrımlarıyla birleştirerek İngiliz ulusal Barok üslubunun zirvesini yaratmıştır.'),
  ('Henry Purcell\'in 1689 civarında Londra\'daki Chelsea yatılı kız okulunda sahnelenmek üzere Vergilius\'un \'Aeneis\' destanından uyarladığı, baştan sona müzikli tek gerçek operası hangisidir?', 'Dido and Aeneas', ['Acis ve Galatea', 'Dilenci Operası', 'Kral Arthur'], 'Nahum Tate\'in librettosuyla bir saatlik kusursuz bir mücevher gibi kurgulanan \'Dido and Aeneas\', Kartaca Kraliçesi Dido ile Truvalı prens Aeneas\'ın trajik aşkını ve büyücülerin entrikasını anlatır.'),
  ('Venedik\'te hem Giovanni Gabrieli\'den hem daha sonra Monteverdi\'den ders alarak İtalyan çok korolu ve concertato üslubunu Almanca İncil metinlerine aktaran ve \'Alman Barok müziğinin babası\' sayılan 17. yüzyıl bestecisi kimdir?', 'Heinrich Schütz', ['Michael Praetorius', 'Samuel Scheidt', 'Johann Hermann Schein'], 'J. S. Bach\'tan tam yüz yıl önce (1585\'te!) doğan Heinrich Schütz (1585–1672), \'Psalmen Davids\', \'Symphoniae sacrae\', \'Musikalische Exequien\' ve eşliksiz pasyonlarıyla Alman Protestan müziğini dönüştürmüştür.'),
  ('1705 sonbaharında yirmi yaşındaki genç orgcu Johann Sebastian Bach\'ın, çalıştığı Arnstadt kilisesinden dört haftalık izin alıp yürüyerek dört yüz kilometre uzaktaki Lübeck\'e gitmesinin ve iznini dört aya uzatmasının amacı neydi?', 'Yaşlı usta Dietrich Buxtehude\'nin org sanatını ve Abendmusiken konserlerini yerinde dinleyip öğrenmek', ['Danimarka Kralı\'nın sarayında açık bulunan başkemancılık sınavına girmek', 'İngiltere\'ye giden bir ticaret gemisine binerek Londra\'da Handel ile buluşmak', 'Venedik\'ten kuzey limanlarına getirilen Stradivari kemanlarını satın almak'], 'Hem Handel ve Mattheson (1703\'te) hem de genç Bach (1705\'te) Lübeck\'e Buxtehude\'yi ziyarete gitmiş; ancak her üç genç de Buxtehude\'nin makamını devralma koşulu olan \'en büyük kızıyla evlenme\' şartını kabul etmemiştir.'),
  ('Orta Almanya\'nın Thüringen bölgesinde iki yüzyıl boyunca yetmişten fazla orgcu, şehir çalgıcısı ve kantor yetiştirdiği için bölgede \'müzisyen\' kelimesiyle eşanlamlı hale gelen soyadı hangisidir?', 'Bach ailesi', ['Couperin hanedanı', 'Amati sülalesi', 'Gabrieli amca-yeğeni'], 'Değirmenci Veit Bach\'tan başlayarak Eisenach, Erfurt ve Arnstadt\'ta kuşaklar boyu müzik loncalarını dolduran Bach ailesi öylesine kalabalıktı ki Erfurt\'ta şehir müzisyenlerine soyadları başka olsa bile halk arasında \'Bach\'lar\' denirdi.'),
  ('J. S. Bach\'ın tüm müzik dünyasında en tanınan org eseri olan ve çarpıcı mordent motifinin ardından sarsıcı eksiltilmiş yedili akorlarıyla gürleyen \'BWV 565\' numaralı başyapıtı hangisidir?', 'Re Minör Toccata ve Füg', ['Do Minör Passacaglia ve Füg', 'Sol Minör Küçük Füg', 'Mi Bemol Majör Aziz Anne Fügü'], 'Üç oktavda ünison çalınan ikonik açılış çağrısı ve rapsodik arpejleriyle BWV 565 Re Minör Toccata ve Füg, Barok org edebiyatının en meşhur simgesidir.'),
  ('J. S. Bach\'ın dört adet \'Orkestra Süiti\' (Uvertür, BWV 1066–1069) arasında; 3. Süit\'teki ünlü \'Sol Telinde Arya\' (Air) ile 2. Süit\'in sonundaki kıvrak \'Badinerie\' bölümleri sırasıyla hangi çalgı kadrolarıyla özdeşleşmiştir?', 'Yaylı çalgılar topluluğu – Solo yan flüt ve yaylılar', ['Solo trompet ve org – Çift klavsen ve timpani', 'Solo obua d\'amore – Dört korno ve fagot grubu', 'Solo viyolonsel – Eşliksiz dört sesli koro'], 'Re majör 3. Orkestra Süiti\'nin 2. bölümü \'Air\' yalnızca yaylılar ve sürekli bas içindir (19. yy\'da Wilhelmj kemanın Sol teline uyarlamıştır); Si minör 2. Orkestra Süiti\'nin şakacı finali \'Badinerie\' ise flauto traverso dağarcığının en meşhur parçasıdır.'),
  ('Bach\'ın ölümüyle yaklaşık seksen yıl kilise arşivlerinde unutulmaya yüz tutan \'Matta Pasyonu\'nu 1829 yılında Berlin Singakademie\'de yirmi yaşındayken yöneterek büyük \'19. yüzyıl Bach Uyanışı\'nı başlatan Romantik besteci kimdir?', 'Felix Mendelssohn Bartholdy', ['Richard Wagner', 'Hector Berlioz', 'Pyotr İlyiç Çaykovski'], 'Büyükannesinin genç Mendelssohn\'a Matta Pasyonu\'nun el yazması kopyasını Noel hediyesi olarak vermesiyle başlayan serüven, 11 Mart 1829 Berlin konseriyle Bach\'ı tarihin en büyük evrensel bestecilerinden biri olarak yeniden dünya sahnesine çıkarmıştır.'),
  ('Protestan bir besteci olmasına karşın J. S. Bach\'ın yaşamının son yıllarında önceki seçkin parodilerini de birleştirerek Katolik Latin \'Missa tota\' (Kyrie, Gloria, Credo, Sanctus, Agnus Dei) tam metni üzerine inşa ettiği evrensel vokal zirvesi hangisidir?', 'Si Minör Missa', ['Magnificat Re Majör', 'Paskalya Oratoryosu', 'Yuhanna Pasyonu'], 'İlk iki bölümünü (Kyrie ve Gloria) 1733\'te Katolik Saksonya Elektörü\'ne sunan, son yıllarında (1748–1749) ise \'Symbolum Nicenum\' (Credo) ve Agnus Dei ile tamamlayan Bach, \'Si Minör Büyük Ayin\' (BWV 232) ile tüm yaşamının vokal sanat özetini bırakmıştır.'),
  ('Bach\'ın 1734–1735 Noel dönemindeki altı ayrı ayin günü için (25 Aralık\'tan 6 Ocak Epifani Bayramı\'na dek) seslendirilmek üzere altı bağlı kantat halinde kurguladığı neşeli başyapıtı hangisidir?', 'Noel Oratoryosu', ['Göğe Yükseliş Oratoryosu', 'Yaratılış Haftası Kantatı', 'Mesih Oratoryosu'], '\'Jauchzet, frohlocket!\' (Sevinin, coşun!) timpani ve trompetleriyle açılan \'Weihnachts-Oratorium\' (BWV 248), tek gecelik bir konser eseri değil Noel bayramının altı ayrı gününe yayılan görkemli bir altı-kantat dizisidir.'),
  ('Katolik Kilisesi ayinlerinde eşliksiz ve tek sesli olarak Latince seslendirilen geleneksel Orta Çağ ezgilerine ne ad verilir?', 'Gregoryen ezgisi', ['Polifonik motet', 'Madrigal şarkısı', 'Koral prelüd'], 'Papa I. Gregorius ile özdeşleştirilen Gregoryen ezgileri (chant), Orta Çağ kilise müziğinin temelini oluşturan monofonik ve çalgı eşliksiz ilahilerdir.'),
  ('Dört çizgili dizek yapısını ve "Ut, Re, Mi, Fa, Sol, La" nota hecelerini müzik eğitimine kazandıran Orta Çağ kuramcısı kimdir?', 'Guido d\'Arezzo', ['Hildegard von Bingen', 'Philippe de Vitry', 'Guillaume de Machaut'], '11. yüzyılda yaşayan İtalyan keşiş Guido d\'Arezzo, Aziz Ioannes ilahisinin ilk hecelerini kullanarak solfej sisteminin temelini atmıştır.'),
  ('Orta Çağ\'da Güney Fransa\'da Oksitan dilinde şövalyelik ve saray aşkı temalı şiirler yazıp besteleyen gezgin şair-müzisyenlere ne denir?', 'Trubadur', ['Minnesänger', 'Meistersinger', 'Kastrato'], 'Güney Fransa\'daki soylu ya da gezgin ozanlara trubadur (troubadour), Kuzey Fransa\'dakilere trouvère, Almanya\'dakilere ise Minnesänger adı verilmiştir.'),
  ('Antonio Vivaldi\'nin keman ve yaylı orkestrası için bestelediği ünlü "Dört Mevsim" adlı yapıtı hangi müzik formundadır?', 'Keman konçertosu dizisi', ['Solo keman sonatı', 'Yaylı çalgılar süiti', 'Dinî oratoryo'], 'Opus 8 "Il cimento dell\'armonia e dell\'inventione" içinde yer alan Dört Mevsim (Le quattro stagioni), her biri üç bölümlü dört ayrı keman konçertosundan oluşur.'),
  ('Ünlü "Hallelujah" korosunu da barındıran İngilizce "Messiah" (Mesih) adlı eserin bestecisi kimdir?', 'George Frideric Handel', ['Johann Sebastian Bach', 'Henry Purcell', 'Georg Philipp Telemann'], 'Handel\'in 1741 yılında yalnızca yirmi dört günde tamamladığı "Messiah", müzik tarihinin en tanınmış oratoryolarından biridir.'),
  ('Barok dönemde tellerinin mızrap benzeri küçük tüy veya deri uçlarla çekilmesiyle ses üreten klavyeli çalgı hangisidir?', 'Klavsen', ['Modern kuyruklu piyano', 'Çelesta', 'Körüklü kilise orgu'], 'Klavsen (harpsichord), tuşa basıldığında mekanizmanın teli çekmesi prensibiyle çalışır; tellere çekiçle vuran piyanodan bu yönüyle ayrılır.'),
  ('Johann Sebastian Bach\'ın her majör ve minör tonda prelüd ve fügler içeren iki ciltlik anıtsal klavye yapıtı hangisidir?', 'İyi Düzenlenmiş Klavye', ['Brandenburg Konçertoları', 'Müzikal Sunu', 'İtalyan Konçertosu'], '"Das Wohltemperierte Klavier" (İyi Düzenlenmiş Klavye), iki cildinin her birinde 24\'er prelüd ve füg olmak üzere toplam 48 parçadan oluşur.'),
  ('Barok dönemde sahne tasarımı ve kostüm kullanılmadan kutsal metinler üzerine solistler, koro ve orkestra için yazılan büyük çaplı esere ne ad verilir?', 'Oratoryo', ['Opera seria', 'Konçerto grosso', 'Sinfonia'], 'Oratoryo yapısal olarak operaya benzese de tiyatral oyunculuk, dekor ve kostüm içermez; çoğunlukla dinî ya da destansı konuları işler.'),
  ('Rönesans döneminde çalgı eşliği olmadan yalnızca insan sesleriyle icra edilen koro müziğini tanımlayan İtalyanca terim nedir?', 'A cappella', ['Basso continuo', 'Col legno', 'Senza sordino'], '"Şapel üslubunda" anlamına gelen a cappella terimi, Rönesans\'ın çok sesli koro geleneğinde çalgı eşliksiz vokal müziği ifade eder.'),
  ('Barok çağda çelloya benzeyen ancak perdeli sapı, altı ya da yedi teli bulunan ve bacaklar arasında tutularak çalınan yaylı çalgı hangisidir?', 'Viola da gamba', ['Viola d\'amore', 'Lirone', 'Baryton'], '"Bacak viyolü" anlamına gelen viola da gamba, perdeli tuşesi ve avuç içi yukarı bakacak şekilde tutulan yayıyla modern çellodan ayrılır.'),
  ('Müzik tarihinde "Barok" kelimesinin kökeni hangi sanatsal imgeye dayanmaktadır?', 'Düzensiz biçimli inci', ['Kusursuz mermer sütun', 'Altın yaldızlı kubbe', 'Yedi telli antik lir'], 'Portekizce "barroco" sözcüğünden türeyen terim, başlangıçta biçimsiz veya düzensiz inciyi tanımlamak için kullanılmış, sonradan dönemin süslü üslubuna ad olmuştur.'),
  ('Domenico Scarlatti müzik tarihinde en çok hangi çalgı ve formda verdiği yaklaşık 555 eserle tanınır?', 'Tek bölümlü klavye sonatları', ['Çok sesli kilise kantatları', 'Keman ve flüt konçertoları', 'Fransız üvertürlü süitler'], 'İtalyan asıllı besteci Domenico Scarlatti, büyük çoğunluğu ikili formda ve klavsen için yazılmış 555 özgün sonatıyla klavye tekniğini geliştirmiştir.'),
  ('Barok müzikte bir notanın hemen üstündeki ya da altındaki komşu sesle hızlıca nöbetleşerek duyurulmasına dayanan temel süsleme hangisidir?', 'Tril', ['Glissando', 'Pizzicato', 'Tremolo'], 'Tril, esas nota ile bir üst (veya bağlama göre yardımcı) sesin hızla ardışık çalınmasıyla elde edilen en yaygın Barok süslemelerindendir.'),
  ('Rönesans döneminin sonlarında İtalya\'nın Floransa kentinde toplanan Camerata topluluğunun antik Yunan dramasını canlandırma çabası hangi türü doğurmuştur?', 'Opera', ['Füg', 'Motet', 'Pavane'], 'Floransa Camerata\'sının "monodi" (eşlikli tek ezgi) arayışı, Jacopo Peri\'nin "Dafne" ve "Euridice" eserleriyle ilk operaların doğmasını sağlamıştır.'),
  ('Johann Sebastian Bach\'ın toplam altı adet bestelediği ve adını sunulduğu Alman soylusundan alan orkestra eserleri dizisi hangisidir?', 'Brandenburg Konçertoları', ['İngiliz Süitleri', 'Goldberg Çeşitlemeleri', 'Fransız Süitleri'], 'Bach, farklı çalgı gruplarını bir araya getirdiği altı konçertosunu 1721 yılında Brandenburg-Schwedt Uçbeyi Christian Ludwig\'e ithaf etmiştir.'),
  ('Rönesans döneminde özellikle saray ve ev toplantılarında söylenen, din dışı şiirler üzerine yazılmış çok sesli vokal türe ne ad verilir?', 'Madrigal', ['Koral', 'Oratoryo', 'Reçitatif'], '16. yüzyıl İtalya\'sında ve İngiltere\'sinde zirveye ulaşan madrigal, şiirdeki duygu ve kelimeleri müzikle betimleyen çok sesli din dışı bir şarkı türüdür.'),
  ('Fransız Barok klavsen okulunun önde gelen ismi olup "Büyük" (Le Grand) lakabıyla anılan ve "Klavsen Çalma Sanatı" kitabını yazan besteci kimdir?', 'François Couperin', ['Jean-Baptiste Lully', 'Marc-Antoine Charpentier', 'Marin Marais'], 'Besteci bir aileden gelen François Couperin, zarif karakter parçaları ve 1716\'da yayımladığı "L\'Art de toucher le clavecin" adlı pedagojik eseriyle ünlüdür.'),
  ('Venedik\'teki Ospedale della Pietà adlı kız yetimhanesinde uzun yıllar keman öğretmenliği ve müzik direktörlüğü yapan kızıl saçlı rahip besteci kimdir?', 'Antonio Vivaldi', ['Arcangelo Corelli', 'Tomaso Albinoni', 'Giuseppe Tartini'], 'Saçlarının rengi ve rahipliği nedeniyle "Il Prete Rosso" (Kızıl Rahip) lakabıyla tanınan Vivaldi, konçertolarının çoğunu bu kurumdaki yetenekli kız orkestrası için yazmıştır.'),
  ('Orta Çağ\'da armut biçimli gövdesi, arkaya kıvrık sapı ve çift sıra telleriyle İslam dünyasından Avrupa\'ya geçerek Rönesans\'ın en gözde ev çalgısı olan enstrüman hangisidir?', 'Lavta', ['Klavikord', 'Kornetto', 'Çembalo'], 'Arapça "el-ud" kelimesinden türeyen lavta (lute), Rönesans boyunca hem solo repertuvarda hem de vokal eşliğinde Avrupa\'nın en yaygın telli çalgısı olmuştur.'),
  ('Barok dönemde hem opera hem de oratoryolarda olay örgüsünü ilerletmek amacıyla konuşma ritmine yakın bir üslupla seslendirilen bölüme ne denir?', 'Reçitatif', ['Arya', 'Ritornello', 'Stretto'], 'Reçitatif, metnin anlaşılırlığını ve dramatik akışı ön planda tutarak şarkıcının konuşur gibi esnek bir ritimle söylediği bölümdür.'),
  ('İngiltere Kralı I. George\'un Thames Nehri üzerindeki tekne gezintisi için George Frideric Handel tarafından bestelenen ünlü orkestra eseri hangisidir?', 'Su Müziği', ['Kraliyet Havai Fişek Müziği', 'Acis ve Galatea', 'İsrail Mısır\'da'], 'Handel\'in "Water Music" (Su Müziği) adlı üç süitlik eseri, 1717 yılında kralın teknesine eşlik eden elli kişilik bir müzisyen mavnasında ilk kez seslendirilmiştir.'),
  ('Rönesans döneminde Katolik Kilisesi\'nin Karşı-Reform sürecinde çok sesli koro müziğinin metin anlaşılırlığını koruduğunu kanıtlayan "Papa Marcellus Missası"nın bestecisi kimdir?', 'Giovanni Pierluigi da Palestrina', ['Orlando di Lasso', 'Josquin des Prez', 'Tomás Luis de Victoria'], 'Palestrina, dengeli kontrpuan tekniği ve berrak vokal yazısıyla Trento Konsili\'nin kilise müziğine yönelik eleştirilerini gideren örnek besteci sayılmıştır.'),
  ('Barok çalgı süitini oluşturan Allemande, Courante, Sarabande ve Gigue bölümlerinin ortak tarihsel kökeni nedir?', 'Farklı uluslara ait saray ve halk dansları olmaları', ['Katolik ayinindeki dua metinlerinden uyarlanmaları', 'İtalyan halk tiyatrosundaki doğaçlama sahneler olmaları', 'Askerî geçit törenlerinde çalınan marşlardan türemeleri'], 'Barok süit, kökeni Almanya, Fransa, İspanya ve Britanya adalarına dayanan farklı karakter ve tempodaki stilize dans bölümlerinin art arda dizilmesiyle oluşur.'),
  ('Barok dönemde eserin başından sonuna kadar kesintisiz sürerek armonik temeli sağlayan bas partisine ne ad verilir?', 'Sürekli bas', ['Cantus firmus', 'Ostinato tema', 'Kontrsuje'], 'Basso continuo, bir bas çalgısı (çello, viola da gamba, fagot) ile akorları doğaçlama tamamlayan klavyeli veya telli bir çalgının (klavsen, org, teorbo) ortaklığıyla yürütülür.'),
];
